function assertNonNegativeFinite(name, value) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a finite nonnegative number`);
  }
}

export function retryDelay(attempt, { baseDelay = 10, maxDelay = 1000 } = {}) {
  assertPositiveInteger('attempt', attempt);
  assertNonNegativeFinite('baseDelay', baseDelay);
  assertNonNegativeFinite('maxDelay', maxDelay);
  if (baseDelay === 0) {
    return 0;
  }
  const exponent = attempt - 1;
  const scaled = baseDelay * 2 ** exponent;
  if (!Number.isFinite(scaled)) {
    return maxDelay;
  }
  return Math.min(maxDelay, scaled);
}

